package main

import "fmt"

// Define a named type so the enum is type-safe (not just int).
type Weekday int

// iota starts at 0 in this block; each line increments it by 1.
const (
	Sunday Weekday = iota // 0
	Monday                // 1 (expression 'iota' implicitly repeated)
	Tuesday               // 2
	Wednesday             // 3
	Thursday              // 4
	Friday                // 5
	Saturday              // 6
)

// String implements fmt.Stringer for readable output.
func (d Weekday) String() string {
	names := [...]string{"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"}
	if d < Sunday || d > Saturday {
		return fmt.Sprintf("Weekday(%d)", int(d))
	}
	return names[d]
}

func main() {
	today := Wednesday
	fmt.Println(today, "=", int(today)) // uses String() then the numeric value
	fmt.Println("is weekend:", today == Saturday || today == Sunday)
}

package main

import "fmt"

// Permission bit flags: each is a distinct power of two via 1 << iota.
type Permission uint8

const (
	Read  Permission = 1 << iota // 1 << 0 = 1
	Write                        // 1 << 1 = 2
	Exec                         // 1 << 2 = 4
)

// Byte size units using iota in an arithmetic expression.
const (
	_  = iota             // skip 0 (the bytes case)
	KB = 1 << (10 * iota) // 1 << 10
	MB                    // 1 << 20
	GB                    // 1 << 30
)

func main() {
	// Combine flags with bitwise OR.
	perm := Read | Write
	fmt.Printf("perm bits: %03b\n", perm)            // 011
	fmt.Println("can write:", perm&Write != 0)        // test a flag
	fmt.Println("can exec:", perm&Exec != 0)

	fmt.Println("KB:", KB, "MB:", MB, "GB:", GB)
}
